(()=>{const isAr=document.documentElement.lang==='ar'||location.pathname.startsWith('/ar/');const p=isAr?'/ar':'';const labels=isAr?{home:'الرئيسية',perfume:'العطور',spray:'البخاخات الفاخرة',oud:'العود والبخور',discovery:'اكتشف',gift:'الهدايا والتغليف',voucher:'قسيمة هدية',wedding:'الأعراس',b2b:'قطاع الأعمال'}:{home:'Home',perfume:'Perfume',spray:'Luxury Spray',oud:'Oud & Bakhoor',discovery:'Discovery',gift:'Gift & Wrap',voucher:'Gift Voucher',wedding:'Wedding',b2b:'B2B'};function install(){const header=document.querySelector('header');if(!header)return;if(header.querySelector('.unified-main-nav'))return;header.querySelector('#main-navigation')?.setAttribute('hidden','');header.querySelector('.menu-toggle')?.setAttribute('hidden','');header.querySelector('.desktop-luxury-nav')?.remove();const nav=document.createElement('nav');nav.className='unified-main-nav';nav.setAttribute('aria-label','Main navigation');nav.innerHTML=`<a href="${p}/">${labels.home}</a><a href="${p}/shop/?collection=perfume#collection">${labels.perfume}</a><a href="${p}/room-sprays/">${labels.spray}</a><a href="${p}/oud-bakhoor/">${labels.oud}</a><span class="unified-discovery"><button type="button" aria-expanded="false">${labels.discovery} <span aria-hidden="true">⌄</span></button><span class="unified-discovery-menu"><a href="${p}/shop/?collection=gift#collection">${labels.gift}</a><a href="${p}/shop/?collection=gift-voucher#collection">${labels.voucher}</a></span></span><a href="${p}/wedding-events/">${labels.wedding}</a><a href="${p}/b2b/">${labels.b2b}</a>`;header.appendChild(nav);const btn=nav.querySelector('.unified-discovery>button');const menu=nav.querySelector('.unified-discovery-menu');btn.addEventListener('click',e=>{e.stopPropagation();const open=btn.getAttribute('aria-expanded')==='true';btn.setAttribute('aria-expanded',String(!open));menu.classList.toggle('open',!open)});document.addEventListener('click',()=>{btn.setAttribute('aria-expanded','false');menu.classList.remove('open')});const style=document.createElement('style');style.id='unified-main-nav-style';style.textContent=`header{overflow:visible!important}.unified-main-nav{display:flex!important;visibility:visible!important;opacity:1!important;align-items:center!important;justify-content:center!important;gap:clamp(20px,2.8vw,48px)!important;width:100%!important;height:48px!important;background:#fffdfa!important;position:relative!important;z-index:120!important}.unified-main-nav>a,.unified-main-nav button{color:#17130f!important;font:500 11px/48px var(--sans,Arial,sans-serif)!important;letter-spacing:.35px!important;text-transform:uppercase!important;white-space:nowrap!important;text-decoration:none!important;border:0!important;background:transparent!important;padding:0!important;cursor:pointer!important}.unified-discovery{position:relative;display:inline-flex;height:48px}.unified-discovery-menu{display:none;position:absolute;top:43px;left:50%;transform:translateX(-50%);min-width:170px;padding:8px 0;background:#fffdfa;border:1px solid #e8ded0;box-shadow:0 10px 25px rgba(0,0,0,.08);z-index:999}.unified-discovery-menu.open{display:block}.unified-discovery-menu a{display:block;padding:10px 16px;color:#17130f;text-decoration:none;font:500 11px/1.3 var(--sans,Arial,sans-serif);white-space:nowrap;text-transform:uppercase}html[lang="ar"] .unified-main-nav>a,html[lang="ar"] .unified-main-nav button,html[lang="ar"] .unified-discovery-menu a{font-size:13px!important;text-transform:none!important;letter-spacing:0!important}@media(min-width:851px){header{grid-template-rows:112px 48px!important}.unified-main-nav{grid-column:1/-1!important;grid-row:2!important}}@media(max-width:850px){header{height:auto!important;min-height:0!important;padding:10px 0 0!important;display:grid!important;grid-template-columns:1fr auto 1fr!important;grid-template-rows:96px 48px!important;align-items:center!important;background:#fffdfa!important;overflow:visible!important}header>.brand{grid-column:2!important;grid-row:1!important;justify-self:center!important;position:static!important;transform:none!important;width:70px!important;height:86px!important;margin:0!important}header>.brand img{width:100%!important;height:100%!important;object-fit:contain!important}header>.header-actions{grid-column:3!important;grid-row:1!important;justify-self:end!important;margin-right:12px!important;display:flex!important;gap:4px!important}header>.menu-toggle,header>#main-navigation{display:none!important}.unified-main-nav{grid-column:1/-1!important;grid-row:2!important;justify-content:flex-start!important;gap:22px!important;overflow-x:auto!important;overflow-y:visible!important;padding:0 16px!important;box-sizing:border-box!important;scrollbar-width:none!important;-webkit-overflow-scrolling:touch!important}.unified-main-nav::-webkit-scrollbar{display:none}.unified-main-nav>a,.unified-main-nav button{font-size:10px!important;line-height:48px!important}.unified-discovery-menu{position:fixed!important;top:auto!important;left:50%!important;transform:translateX(-50%)!important;margin-top:43px!important}.desktop-header-left{display:none!important}}`;document.getElementById('unified-main-nav-style')?.remove();document.head.appendChild(style)}if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',install,{once:true});else install();})();